<script setup lang="ts">
import { ref } from 'vue';
import { api } from '../services/api';
type Json=Record<string,unknown>;
const props=defineProps<{station:string;runId?:string;runStatus?:string;canWrite:boolean;admin:boolean}>();
const emit=defineEmits<{'select-procedure':[value:Json]}>();
const target=ref(''),topology=ref<Json|null>(null),branches=ref<Json|null>(null),analysis=ref<Json|null>(null);
const procedures=ref<Json[]>([]),loaded=ref(false),busy=ref(false),error=ref(''),notice=ref('');
const title=ref(''),assetKind=ref(''),procedureStation=ref('P5');
const steps=ref('[\n  {"tool":"asset_snapshot","args":{"asset_code":"FLAME-05"},"expectedEvidence":"取得目标设备的新鲜观测与质量","stopCondition":"目标不存在或观测不可用时停止并补证"}\n]');
const sourceRefs=ref('RUNBOOK:sensor');
const states:Record<string,string>={candidate:'候选，未批准',approved:'管理员已批准',rejected:'已驳回',retired:'已退役'};
const rows=(value:unknown):Json[]=>Array.isArray(value)?value.filter(item=>item&&typeof item==='object') as Json[]:[];
const object=(value:unknown):Json=>value&&typeof value==='object'&&!Array.isArray(value)?value as Json:{};
const display=(value:unknown)=>typeof value==='string'?value:value==null?'未知':JSON.stringify(value);
const relationNames:Record<string,string>={owned_by:'归属主控',telemetry_via:'遥测经过',has_feedback:'反馈来源',located_at:'所在检测站',bound_to_mesh:'已验证三维绑定',expected_mapping:'预期映射'};
const branchStatuses:Record<string,string>={needs_parameters:'缺少明确场景参数',unsupported_source:'该来源不能用于现场预测',compared:'已计算场景分支',completed:'已计算场景分支'};
function fail(cause:unknown){const response=(cause as {response?:{status?:number;data?:{message?:string}}}).response;error.value=response?.status===409?'模板已被更新，请刷新后重新核对版本。':response?.data?.message || (cause instanceof Error ? cause.message : '读取失败，请检查服务、登录状态或重试。');}
async function request(action:()=>Promise<void>){if(busy.value)return;if(!sessionStorage.getItem('ut-django-token')){error.value='请先登录数据服务再使用此工具。';return;}busy.value=true;error.value='';notice.value='';try{await action();}catch(cause){fail(cause);}finally{busy.value=false;}}
function loadTopology(){return request(async()=>{topology.value=(await api.agentTopology(target.value.trim()||props.station)).data;});}
function compare(){if(!props.runId || ['queued','running'].includes(props.runStatus||''))return;return request(async()=>{branches.value=(await api.compareAgentBranches(props.runId!)).data;});}
function inspectFailure(){if(!props.runId)return;return request(async()=>{analysis.value=(await api.agentRunAnalysis(props.runId!)).data;});}
async function refreshProcedures(){const {data}=await api.agentProcedures();procedures.value=Array.isArray(data)?data:data.items||[];loaded.value=true;}
function loadProcedures(){return request(refreshProcedures);}
function extractProcedure(){if(!props.canWrite||!props.runId||props.runStatus!=='completed')return;return request(async()=>{await api.extractAgentProcedure(props.runId!);await refreshProcedures();notice.value='已从本任务成功的只读工具轨迹整理候选，尚未批准；不会自动执行或发布。';});}
function createProcedure(){if(!props.canWrite)return;return request(async()=>{let parsed:unknown;try{parsed=JSON.parse(steps.value);}catch{throw new Error('检查步骤不是有效JSON，请修正格式后提交。');}if(!Array.isArray(parsed)||!parsed.length)throw new Error('至少填写一个只读检查步骤。');if(!title.value.trim())throw new Error('请填写检查模板名称。');await api.createAgentProcedure({title:title.value.trim(),station_id:procedureStation.value,...(assetKind.value.trim()?{asset_kind:assetKind.value.trim()}:{}),steps:parsed,source_refs:sourceRefs.value.split(/[,，\s]+/).filter(Boolean),...(props.runId?{source_run_id:props.runId}:{})});await refreshProcedures();notice.value='已保存为待审核候选，尚不能作为已批准技能执行。';});}
function review(item:Json,action:'approve'|'reject'|'retire'){if(!props.admin)return;return request(async()=>{await api.reviewAgentProcedure(String(item.id),action,Number(item.revision));await refreshProcedures();notice.value='审核状态已更新；审批不等于已取得现场测量。';});}
</script>
<template>
  <div class="capability-tools">
    <p v-if="error" role="alert" class="error">{{ error }}</p><p v-if="notice" role="status" class="notice">{{ notice }}</p>
    <details class="tool-section"><summary>设备关联与影响范围<span>只查询已配置关系</span></summary><div class="tool-content"><p>关系图不推断未配置的接线或真实供电，不根据三维坐标生成电气连接。</p><form class="actions" @submit.prevent="loadTopology"><label>目标设备或检测站<input v-model="target" :placeholder="station" maxlength="50" /></label><button :disabled="busy" type="submit">查询设备关联</button></form><template v-if="topology"><p>目标 {{ topology.target || '见关系记录' }} · 配置版本 {{ topology.version || topology.topologyVersion || '未记录' }}</p><div v-if="rows(topology.edges).length" class="table-wrap"><table><thead><tr><th>对象</th><th>配置关系</th><th>关联对象</th><th>验证标记</th></tr></thead><tbody><tr v-for="(edge,index) in rows(topology.edges)" :key="index"><td>{{ edge.from }}</td><td>{{ relationNames[String(edge.kind)] || edge.kind }}</td><td>{{ edge.to }}</td><td>{{ edge.verified === true ? '绑定已核对' : '配置关系，非接线实测' }}</td></tr></tbody></table></div><p v-if="rows(topology.missing).length" class="help">存在未配置或无法核验的关系，请查看缺项记录。</p><details><summary>完整关系、缺项与影响范围</summary><pre>{{ JSON.stringify(topology,null,2) }}</pre></details></template></div></details>
    <details class="tool-section"><summary>独立分支推演与失败分析<span>使用所选任务的冻结证据</span></summary><div class="tool-content"><p>分支不重置全局演示库。缺少通风响应或功率参数时显示缺项，不生成真实浓度下降或节能承诺。</p><p class="help">{{ runId ? `当前任务：${runId}` : '先选择一项任务，再进行分支比较或失败分析。' }}</p><div class="actions"><button :disabled="busy || !runId || ['queued','running'].includes(runStatus || '')" @click="compare">比较隔离仿真分支</button><button :disabled="busy || !runId" @click="inspectFailure">分析本任务轨迹</button></div><section v-if="branches"><h3>分支结果与假设</h3><p>{{ branchStatuses[String(branches.status)] || branches.status }} · {{ object(branches.comparison).reason || '比较条件见完整记录' }}</p><p class="help">快照 {{ branches.snapshotHash || '未记录' }} · 场景模型 {{ branches.responseModelVersion || branches.modelVersion || '未记录' }}</p><article v-for="branch in rows(branches.branches)" :key="String(branch.id)"><h4>{{ branch.label || branch.id }}</h4><p>条件检查：{{ display(branch.constraints) }}</p><div class="table-wrap"><table><thead><tr><th>模拟风机</th><th>模拟供电</th><th>PWM</th><th>模拟RPM</th><th>模拟功率W</th></tr></thead><tbody><tr v-for="(output,fan) in object(branch.outputs)" :key="fan"><td>{{ fan }}</td><td>{{ object(output).power ?? '未知' }}</td><td>{{ object(output).pwm ?? '未知' }}</td><td>{{ object(output).rpm ?? '未知' }}</td><td>{{ object(output).watts ?? '未知' }}</td></tr></tbody></table></div><p class="help">环境恢复：{{ branch.environmentRecovery === 'unknown' ? '未建立经验证的响应模型，不能判定' : display(branch.environmentRecovery) }}；未发送真实命令，未据回执解除告警。</p></article><details><summary>完整参数假设、缺项、成本与分支记录</summary><pre>{{ JSON.stringify(branches,null,2) }}</pre></details></section><section v-if="analysis"><h3>可定位的违规步骤与缺口</h3><p v-if="analysis.summary || analysis.message">{{ analysis.summary || analysis.message }}</p><pre>{{ JSON.stringify(analysis,null,2) }}</pre></section></div></details>
    <details class="tool-section"><summary>受审只读检查模板<span>审批后复用，逐轮取得新证据</span></summary><div class="tool-content"><p>模板规定检查顺序、预期证据和停止条件；与避坑提醒分别管理，不包含任意代码或硬件控制。</p><button :disabled="busy" @click="loadProcedures">加载检查模板</button><button v-if="canWrite" :disabled="busy || !runId || runStatus!=='completed'" @click="extractProcedure">从本任务提取流程候选</button><p v-if="loaded && !procedures.length" class="help">暂无可见模板。候选经过审核和回归后才可用于调查。</p><article v-for="item in procedures" :key="String(item.id)"><header><h3>{{ item.title }}</h3><span>{{ states[String(item.status)] || item.status }}</span></header><p>{{ item.stationId }} · 版本 {{ item.revision }} · 内容散列 {{ item.contentHash || '未记录' }}</p><details><summary>查看步骤、引用与适用版本</summary><pre>{{ JSON.stringify(item,null,2) }}</pre></details><div v-if="admin" class="actions"><template v-if="item.status==='candidate'"><button :disabled="busy" @click="review(item,'approve')">批准检查模板</button><button :disabled="busy" @click="review(item,'reject')">驳回检查模板</button></template><button v-if="item.status==='approved'" :disabled="busy" @click="review(item,'retire')">退役检查模板</button></div></article>
      <p class="help">已批准模板可准备为下一轮任务；选择后仍需在任务表单中明确启动。</p><div class="approved-choices"><button v-for="item in procedures.filter(item=>item.status==='approved')" :key="String(item.id)" :disabled="busy" @click="emit('select-procedure',item)">准备模板：{{ item.title }}</button></div>
      <details v-if="canWrite" class="candidate-form"><summary>提交只读检查模板候选</summary><form @submit.prevent="createProcedure"><div class="fields"><label>模板名称<input v-model="title" maxlength="120" required /></label><label>适用检测站<select v-model="procedureStation"><option v-for="s in ['P1','P2','P3','P4','P5']" :key="s">{{ s }}</option></select></label><label>设备类别（可选）<input v-model="assetKind" maxlength="50" /></label><label>来源引用编号<input v-model="sourceRefs" placeholder="按空格或逗号分隔" maxlength="500" /></label></div><label>检查步骤JSON<textarea v-model="steps" maxlength="16000" rows="7" spellcheck="false" /></label><p class="help">每步包含tool、args、expectedEvidence和stopCondition；服务端校验工具白名单、目标及引用。接线、规则和知识版本由服务端记录。</p><button :disabled="busy" type="submit">保存模板候选</button></form></details>
    </div></details>
  </div>
</template>
<style scoped>
.capability-tools{display:grid;gap:12px;min-width:0;color:var(--ops-text,#1c3049)}.tool-section{margin:0;padding:0 24px;border:1px solid var(--ops-line,#d8e2ee);border-radius:12px;background:var(--ops-panel,#fff);min-width:0}.tool-section>summary{min-height:72px;box-sizing:border-box;padding:22px 0;font-size:15px;font-weight:700;color:var(--ops-text,#1c3049)}summary{cursor:pointer;min-height:36px;color:var(--ops-signal,#1766c3);font-size:13px}.tool-section>summary>span{color:var(--ops-muted,#53657b);font-size:12px;font-weight:400;margin-left:16px}.tool-content{padding:0 0 20px;border-top:1px solid var(--ops-line-soft,#e5ebf3)}p{max-width:75ch;font-size:13px;line-height:1.7;overflow-wrap:anywhere}.help{font-size:12px;color:var(--ops-muted,#53657b)}h3{font-size:14px;margin:16px 0 8px}article{margin-top:20px;padding-top:12px;border-top:1px solid var(--ops-line-soft,#e5ebf3)}header{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap}header span{font-size:12px;color:var(--ops-muted,#53657b)}.actions{display:flex;align-items:end;flex-wrap:wrap;gap:10px;margin:14px 0}.actions>label{flex:1 1 220px}.fields{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin:16px 0}label{display:grid;gap:6px;font-size:12px;font-weight:600;min-width:0}input,select,textarea,button{box-sizing:border-box;max-width:100%;min-height:42px;border:1px solid var(--ops-line,#d8e2ee);border-radius:7px;padding:9px 11px;color:var(--ops-text,#1c3049);background:var(--ops-panel,#fff);font:inherit;font-size:13px}input,select,textarea{width:100%;caret-color:var(--ops-signal,#1766c3)}textarea{resize:vertical;font-family:ui-monospace,monospace;line-height:1.6}button{font-weight:600;cursor:pointer}button:hover:not(:disabled){border-color:var(--ops-signal,#1766c3);background:var(--ops-signal-soft,#eaf3ff)}button:disabled{opacity:.6;cursor:not-allowed}:is(input,select,textarea,button,summary):focus-visible{outline:2px solid var(--ops-signal,#1766c3);outline-offset:3px}pre{overflow:auto;max-width:100%;max-height:360px;background:var(--ops-bg-deep,#f8fafc);padding:12px;font:12px/1.6 ui-monospace,monospace}.candidate-form{margin-top:20px}.approved-choices{display:flex;flex-wrap:wrap;gap:8px}.table-wrap{overflow:auto;max-width:100%}table{width:100%;border-collapse:collapse;font-size:12px}td,th{text-align:left;padding:9px;border-bottom:1px solid var(--ops-line-soft,#e5ebf3);overflow-wrap:anywhere}th{color:var(--ops-muted,#53657b)}h4{font-size:13px;margin:12px 0 8px}.error{color:var(--ops-danger,#b9364d)}.notice{color:var(--ops-ok,#167451)}@media(max-width:560px){.tool-section{padding:0 16px}.tool-section>summary>span{display:block;margin:4px 0 0 16px}.fields{grid-template-columns:1fr}.actions>button{flex:1 1 160px}}
</style>
